def application(
    environ: dict[str, Any], start_response: StartResponse
) -> Iterable[bytes]:
    try:
        method = str(environ.get("REQUEST_METHOD", "GET")).upper()
        path = str(environ.get("PATH_INFO", "/"))

        if path == "/":
            # Global cross-reference summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_cross_reference_summary(
                method, environ, start_response
            )

        if path == "/cross-reference-usage":
            # Per-repository cross-reference usage view; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_cross_reference_usage(
                method, environ, start_response
            )

        if path == "/cross-reference-targets":
            # Per-resolved-local-target cross-reference usage view; the
            # handler answers the 405 (Allow: GET) for every other method.
            return _handle_cross_reference_targets(
                method, environ, start_response
            )

        if method == "GET" and path == "/health":
            # Kept byte-for-byte compatible with the documented baseline.
            return _json_response(start_response, "200 OK", {"status": "ok"})

        if path == "/advisories":
            return _handle_advisories(method, environ, start_response)

        if path == "/graph":
            return _handle_graph(method, environ, start_response)

        if path == "/graph/stats":
            return _handle_graph_stats(method, environ, start_response)

        if path == "/dependency-closure-summary":
            # Per-resource dependency closure size summary; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_dependency_closure_summary(
                method, environ, start_response
            )

        if path == "/dependency-usage":
            # Per-depended-upon-resource dependents usage view; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_dependency_usage(method, environ, start_response)

        if path == "/category-usage":
            # Global resource usage view grouped by normalized
            # category; the handler answers the 405 (Allow: GET) for
            # every other method.
            return _handle_category_usage(method, environ, start_response)

        if path == "/digest-usage":
            # Global resource usage view grouped by registration digest;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_digest_usage(method, environ, start_response)

        if path == "/name-usage":
            # Global resource usage view grouped by registration name;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_name_usage(method, environ, start_response)

        if path == "/source-usage":
            # Global resource usage view grouped by registration source;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_source_usage(method, environ, start_response)

        if path == "/state-usage":
            # Global resource usage view grouped by current lifecycle
            # state; the handler answers the 405 (Allow: GET) for every
            # other method.
            return _handle_state_usage(method, environ, start_response)

        if path == "/graph/path/all":
            return _handle_graph_path_all(method, environ, start_response)

        if path == "/graph/path":
            return _handle_graph_path(method, environ, start_response)

        if path == "/promotion/blockers":
            return _handle_promotion_blockers(method, environ, start_response)

        if path == "/lifecycle":
            # Global lifecycle summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_lifecycle_summary(method, environ, start_response)

        if path == "/dependency-vulnerability-impact":
            # Global dependency vulnerability impact summary; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_global_dependency_vulnerability_impact(
                method, environ, start_response
            )

        if path == "/upload-sessions":
            # Global chunk upload session summary; the handler answers the
            # 405 (Allow: GET) for every other method.
            return _handle_upload_sessions(method, environ, start_response)

        if path == "/content-status":
            # Global finished-content readiness summary; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_content_status(method, environ, start_response)

        if path == "/content-integrity":
            # Global assembled-content digest consistency inspection; the
            # handler answers the 405 (Allow: GET) for every other method.
            return _handle_content_integrity(method, environ, start_response)

        if path == "/vulnerability-exceptions":
            # Global exemption summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_global_vulnerability_exceptions(
                method, environ, start_response
            )

        if path == "/sboms":
            # Global SBOM summary; the handler answers the 405 (Allow: GET)
            # for every other method.
            return _handle_sboms_summary(method, environ, start_response)

        if path == "/licenses":
            # Global license summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_licenses_summary(method, environ, start_response)

        if path == "/provenance":
            # Global build provenance summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_provenance_summary(method, environ, start_response)

        if path == "/signatures":
            # Global content signature summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_signatures_summary(method, environ, start_response)

        if path == "/signature-verification":
            # Global signature verification summary; the handler answers
            # the 405 (Allow: GET) for every other method.
            return _handle_signature_verification(
                method, environ, start_response
            )

        if path == "/signature-keys":
            # Global per-key signature usage summary; the handler answers
            # the 405 (Allow: GET) for every other method.
            return _handle_signature_keys(method, environ, start_response)

        if path == "/risk":
            # Global risk summary; the handler answers the 405 (Allow: GET)
            # for every other method.
            return _handle_risk_summary(method, environ, start_response)

        if path == "/admission-preview":
            # Global admission-preview summary; the handler answers the
            # 405 (Allow: GET) for every other method.
            return _handle_admission_preview_summary(
                method, environ, start_response
            )

        if path == "/component-risks":
            # Global component risk summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_global_component_risks(
                method, environ, start_response
            )

        if path == "/component-fixes":
            # Global component fix summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_component_fixes_summary(
                method, environ, start_response
            )

        if path == "/component-inventory":
            # Global component inventory summary; the handler answers the
            # 405 (Allow: GET) for every other method.
            return _handle_component_inventory(
                method, environ, start_response
            )

        if path == "/component-licenses":
            # Global component license summary; the handler answers the
            # 405 (Allow: GET) for every other method.
            return _handle_component_licenses(
                method, environ, start_response
            )

        if path == "/component-usage":
            # Global component usage summary aggregated by component name;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_component_usage(
                method, environ, start_response
            )

        if path == "/alert-components":
            # Global alert usage summary aggregated by alert component name;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_alert_components(
                method, environ, start_response
            )

        if path == "/fix-coverage":
            # Global per-component fix coverage summary aggregated by alert
            # component name; the handler answers the 405 (Allow: GET) for
            # every other method.
            return _handle_fix_coverage(method, environ, start_response)

        if path == "/fix-coverage-progress":
            # Global per-resource fix coverage progress summary; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_fix_coverage_progress(
                method, environ, start_response
            )

        if path == "/severity-coverage":
            # Global fix coverage summary aggregated by alert severity
            # level; the handler answers the 405 (Allow: GET) for every
            # other method.
            return _handle_severity_coverage(
                method, environ, start_response
            )

        if path == "/advisory-fix-progress":
            # Global fix progress summary aggregated by advisory number;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_advisory_fix_progress(
                method, environ, start_response
            )

        if path == "/advisory-fix-gaps":
            # Global fix gap summary aggregated by advisory/component pair;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_advisory_fix_gaps(
                method, environ, start_response
            )

        if path.startswith("/advisories/"):
            # The identifier segment is validated by the handler; an
            # embedded separator or an empty segment is a bad request. A
            # trailing "/fixes" segment selects the per-advisory component
            # fix view instead of the alert detail view.
            tail = path[len("/advisories/"):]
            if tail.endswith("/fixes"):
                return _handle_advisory_fixes(
                    method, environ, tail[: -len("/fixes")], start_response
                )
            return _handle_advisory_item(
                method, environ, tail, start_response
            )

        if path == "/notifications":
            # Global notification summary; the handler answers the 405
            # (Allow: GET) for every other method.
            return _handle_notifications_summary(
                method, environ, start_response
            )

        if path == "/notification-usage":
            # Global notification usage grouped by channel; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_notification_usage(
                method, environ, start_response
            )

        if path == "/notification-targets":
            # Global notification usage grouped by target; the handler
            # answers the 405 (Allow: GET) for every other method.
            return _handle_notification_targets(
                method, environ, start_response
            )

        if path == "/notification-channel-targets":
            # Global notification usage grouped by channel/target pair;
            # the handler answers the 405 (Allow: GET) for every other
            # method.
            return _handle_notification_channel_targets(
                method, environ, start_response
            )

        if path == "/resources":
            if method == "GET":
                return _handle_resources_get(environ, start_response)
            if method == "POST":
                return _handle_resources_post(environ, start_response)
            return _error(
                start_response,
                "405 Method Not Allowed",
                "method_not_allowed",
                f"Method {method} is not allowed for this path.",
                allowed="GET, POST",
            )

        if path == "/policies":
            return _handle_default_policy(method, environ, start_response)

        if path == "/cache":
            return _handle_cache_root(method, environ, start_response)

        if path == "/cache/status":
            return _handle_cache_status(method, environ, start_response)

        if path.startswith("/cache/layers/"):
            tail = path[len("/cache/layers/"):]
            if tail.endswith("/check"):
                # Read-only write pre-check for the layer path; the digest
                # segment is validated by the handler, so an embedded
                # separator is rejected there as a bad request.
                return _handle_cache_layer_check(
                    method,
                    environ,
                    tail[: -len("/check")],
                    start_response,
                )
            return _handle_cache_layer(
                method, environ, tail, start_response
            )

        if path == "/mirrors":
            return _handle_mirrors(method, environ, start_response)

        if path.startswith("/mirrors/"):
            suffix = path[len("/mirrors/"):]
            marker = "/pull/"
            marker_index = suffix.find(marker)
            if marker_index >= 0:
                # Split on the pull marker even when the id segment embeds a
                # separator, so the pull handler can reject the id as a bad
                # request instead of treating the path as an unknown item.
                return _handle_mirror_pull(
                    method,
                    environ,
                    suffix[:marker_index],
                    suffix[marker_index + len(marker):],
                    start_response,
                )
            if suffix.endswith("/pull"):
                # A pull always names a digest; an empty segment is invalid.
                return _handle_mirror_pull(
                    method,
                    environ,
                    suffix[: -len("/pull")],
                    "",
                    start_response,
                )
            if suffix.endswith("/prefetch"):
                # Split on the prefetch marker even when the id segment
                # embeds a separator, so the handler can reject the id as a
                # bad request instead of treating the path as an unknown
                # item.
                return _handle_mirror_prefetch(
                    method,
                    environ,
                    suffix[: -len("/prefetch")],
                    start_response,
                )
            if suffix.endswith("/probe"):
                # Split on the probe marker even when the id segment embeds
                # a separator, so the handler can reject the id as a bad
                # request instead of treating the path as an unknown item.
                return _handle_mirror_probe(
                    method,
                    environ,
                    suffix[: -len("/probe")],
                    start_response,
                )
            if suffix.endswith("/signature-policy"):
                # Split on the policy marker even when the id segment embeds
                # a separator, so the handler can reject the id as a bad
                # request instead of treating the path as an unknown item.
                return _handle_mirror_signature_policy(
                    method,
                    environ,
                    suffix[: -len("/signature-policy")],
                    start_response,
                )
            head, separator, _tail = suffix.partition("/")
            if not separator:
                return _handle_mirror_item(
                    method, environ, head, start_response
                )
            # Any other suffix embeds a separator in the id segment; the
            # item handler rejects it without touching any state.
            return _handle_mirror_item(
                method, environ, suffix, start_response
            )

        )

    if path.startswith("/resources/"):
        suffix = path[len("/resources/"):]
        head, separator, tail = suffix.partition("/")
        if separator and tail == "dependencies":
            return _handle_dependencies(
                method, environ, head, start_response
            )
        if separator and tail == "dependencies/batch":
            return _handle_dependencies_batch(
                method, environ, head, start_response
            )
        if separator and tail.startswith("dependencies/"):
            return _handle_dependency_item(
                method,
                environ,
                head,
                tail[len("dependencies/"):],
                start_response,
            )
        if separator and suffix.endswith("/dependencies/batch"):
            # Fallback for a separator inside the start id segment so
            # the batch handler rejects it without establishing any
            # edge.
            return _handle_dependencies_batch(
                method,
                environ,
                suffix[: -len("/dependencies/batch")],
                start_response,
            )
        if separator and "/dependencies/" in suffix:
            # Fallback for a separator inside the start id segment so
            # the item handler rejects it without removing any edge.
            malformed_id, _, raw_dependency_id = suffix.rpartition(
                "/dependencies/"
            )
            return _handle_dependency_item(
                method,
                environ,
                malformed_id,
                raw_dependency_id,
                start_response,
            )
        if separator and tail == "impact":
            return _handle_impact(
                method, environ, head, start_response
            )
        if separator and tail == "dependency-vulnerability-impact":
            return _handle_dependency_vulnerability_impact(
                method, environ, head, start_response
            )
        if separator and tail == "verify":
            return _handle_verify(
                method, environ, head, start_response
            )
        if separator and tail == "assemble":
            return _handle_assemble(
                method, environ, head, start_response
            )
        if separator and tail == "content":
            return _handle_content(
                method, environ, head, start_response
            )
        if separator and tail == "lifecycle":
            return _handle_lifecycle(
                method, environ, head, start_response
            )
        if separator and tail == "release-blockers":
            return _handle_release_blockers(
                method, environ, head, start_response
            )
        if separator and tail == "vulnerabilities/batch":
            return _handle_vulnerabilities_batch(
                method, environ, head, start_response
            )
        if separator and tail == "vulnerabilities":
            return _handle_vulnerabilities(
                method, environ, head, start_response
            )
        if separator and tail.startswith("vulnerabilities/"):
            return _handle_vulnerability_item(
                method,
                environ,
                head,
                tail[len("vulnerabilities/"):],
                start_response,
            )
        if separator and tail == "vulnerability-exceptions":
            return _handle_vulnerability_exceptions(
                method, environ, head, start_response
            )
        if separator and tail.startswith("vulnerability-exceptions/"):
            return _handle_vulnerability_exception_item(
                method,
                environ,
                head,
                tail[len("vulnerability-exceptions/"):],
                start_response,
            )
        if separator and tail == "sbom":
            return _handle_sbom(
                method, environ, head, start_response
            )
        if separator and tail == "license":
            return _handle_license(
                method, environ, head, start_response
            )
        if separator and tail == "provenance":
            return _handle_provenance(
                method, environ, head, start_response
            )
        if separator and tail == "policies":
            return _handle_policies(
                method, environ, head, start_response
            )
        if separator and tail == "admission":
            return _handle_admission(
                method, environ, head, start_response
            )
        if separator and tail == "admission-preview":
            return _handle_admission_preview(
                method, environ, head, start_response
            )
        if separator and tail == "admission-closure":
            return _handle_admission_closure(
                method, environ, head, start_response
            )
        if separator and tail == "risk":
            return _handle_risk(
                method, environ, head, start_response
            )
        if separator and tail == "component-risks":
            return _handle_component_risks(
                method, environ, head, start_response
            )
        if separator and tail == "component-fixes":
            return _handle_component_fixes(
                method, environ, head, start_response
            )
        if separator and tail == "notifications":
            return _handle_notifications(
                method, environ, head, start_response
            )
        if separator and tail.startswith("notifications/"):
            return _handle_notification_item(
                method,
                environ,
                head,
                tail[len("notifications/"):],
                start_response,
            )
        if separator and tail == "cross-references":
            return _handle_cross_references(
                method, environ, head, start_response
            )
        if separator and tail == "cross-references/verify":
            return _handle_cross_reference_verify(
                method, environ, head, start_response
            )
        if separator and tail.startswith("cross-references/"):
            return _handle_cross_reference_item(
                method,
                environ,
                head,
                tail[len("cross-references/"):],
                start_response,
            )
        if separator and tail == "signatures/verify":
            return _handle_signature_verify(
                method, environ, head, start_response
            )
        if separator and tail == "signatures":
            return _handle_signatures(
                method, environ, head, start_response
            )
        if separator and tail == "chunks/start":
            return _handle_chunks_start(
                method, environ, head, start_response
            )
        if separator and tail == "chunks/status":
            return _handle_chunks_status(
                method, environ, head, start_response
            )
        if separator and tail.startswith("chunks/"):
            return _handle_chunk(
                method, environ, head, tail[len("chunks/"):],
                start_response,
            )
        if separator and tail == "chunks":
            # The collection path without a chunk index is the upload
            # session reset path: DELETE only; every other method is a
            # 405 whose Allow header names DELETE alone.
            return _handle_chunks_reset(
                method, environ, head, start_response
            )
        if separator and suffix.endswith("/cross-references/verify"):
            # Fallback for a separator inside the id segment on the
            # verify path so the handler rejects the id without
            # contacting any upstream; this precedes the generic
            # /verify (signature) fallback below.
            return _handle_cross_reference_verify(
                method,
                environ,
                suffix[: -len("/cross-references/verify")],
                start_response,
            )
        if separator and suffix.endswith("/verify"):
            # The id segment itself contained a path separator; let the
            # verify handler reject it without reading business data.
            return _handle_verify(
                method, environ, suffix[: -len("/verify")], start_response
            )
        if separator and suffix.endswith("/chunks/start"):
            # Fallback for a separator inside the id segment so the
            # start handler rejects it without creating any session.
            return _handle_chunks_start(
                method,
                environ,
                suffix[: -len("/chunks/start")],
                start_response,
            )
        if separator and suffix.endswith("/chunks/status"):
            # Fallback for a separator inside the id segment so the
            # status handler rejects it without creating any state.
            return _handle_chunks_status(
                method,
                environ,
                suffix[: -len("/chunks/status")],
                start_response,
            )
        if separator and suffix.endswith("/chunks"):
            # Fallback for a separator inside the id segment so the
            # reset handler rejects it without tearing down any session.
            return _handle_chunks_reset(
                method,
                environ,
                suffix[: -len("/chunks")],
                start_response,
            )
        if separator and "/chunks/" in suffix:
            # Same fallback for chunk paths with a separator in the id.
            malformed_id, _, raw_index = suffix.rpartition("/chunks/")
            return _handle_chunk(
                method, environ, malformed_id, raw_index, start_response
            )
        if separator and suffix.endswith("/assemble"):
            return _handle_assemble(
                method, environ, suffix[: -len("/assemble")], start_response
            )
        if separator and suffix.endswith("/content"):
            return _handle_content(
                method, environ, suffix[: -len("/content")], start_response
            )
        if separator and suffix.endswith("/lifecycle"):
            return _handle_lifecycle(
                method,
                environ,
                suffix[: -len("/lifecycle")],
                start_response,
            )
        if separator and suffix.endswith("/release-blockers"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without reading any business data.
            return _handle_release_blockers(
                method,
                environ,
                suffix[: -len("/release-blockers")],
                start_response,
            )
        if separator and suffix.endswith("/vulnerabilities/batch"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without recording any alert.
            return _handle_vulnerabilities_batch(
                method,
                environ,
                suffix[: -len("/vulnerabilities/batch")],
                start_response,
            )
        if separator and suffix.endswith("/vulnerabilities"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without recording any alert.
            return _handle_vulnerabilities(
                method,
                environ,
                suffix[: -len("/vulnerabilities")],
                start_response,
            )
        if separator and "/vulnerabilities/" in suffix:
            # Fallback for a separator inside the id segment of an alert
            # item path so the handler rejects it without removing any
            # alert.
            malformed_id, _, raw_vulnerability_id = suffix.rpartition(
                "/vulnerabilities/"
            )
            return _handle_vulnerability_item(
                method,
                environ,
                malformed_id,
                raw_vulnerability_id,
                start_response,
            )
        if separator and "/vulnerability-exceptions/" in suffix:
            # Fallback for a separator inside the id segment of an
            # exception item path so the handler rejects it without
            # removing any exemption.
            malformed_id, _, raw_exception_id = suffix.rpartition(
                "/vulnerability-exceptions/"
            )
            return _handle_vulnerability_exception_item(
                method,
                environ,
                malformed_id,
                raw_exception_id,
                start_response,
            )
        if separator and suffix.endswith("/vulnerability-exceptions"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without recording any exemption.
            return _handle_vulnerability_exceptions(
                method,
                environ,
                suffix[: -len("/vulnerability-exceptions")],
                start_response,
            )
        if separator and suffix.endswith("/sbom"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without recording any document.
            return _handle_sbom(
                method,
                environ,
                suffix[: -len("/sbom")],
                start_response,
            )
        if separator and suffix.endswith("/license"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without recording any license.
            return _handle_license(
                method,
                environ,
                suffix[: -len("/license")],
                start_response,
            )
        if separator and suffix.endswith("/provenance"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without recording any provenance.
            return _handle_provenance(
                method,
                environ,
                suffix[: -len("/provenance")],
                start_response,
            )
        if separator and suffix.endswith("/policies"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without recording any policy.
            return _handle_policies(
                method,
                environ,
                suffix[: -len("/policies")],
                start_response,
            )
        if separator and suffix.endswith("/admission"):
            # Same fallback so a separator in the id is rejected
            # without performing an evaluation.
            return _handle_admission(
                method,
                environ,
                suffix[: -len("/admission")],
                start_response,
            )
        if separator and suffix.endswith("/admission-preview"):
            # Same fallback so a separator in the id is rejected
            # without computing a preview.
            return _handle_admission_preview(
                method,
                environ,
                suffix[: -len("/admission-preview")],
                start_response,
            )
        if separator and suffix.endswith("/admission-closure"):
            # Same fallback so a separator in the id is rejected
            # without computing a closure.
            return _handle_admission_closure(
                method,
                environ,
                suffix[: -len("/admission-closure")],
                start_response,
            )
        if separator and suffix.endswith("/risk"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without computing any score.
            return _handle_risk(
                method,
                environ,
                suffix[: -len("/risk")],
                start_response,
            )
        if separator and suffix.endswith("/component-risks"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without computing any component risk.
            return _handle_component_risks(
                method,
                environ,
                suffix[: -len("/component-risks")],
                start_response,
            )
        if separator and suffix.endswith("/component-fixes"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without computing any fix recommendation.
            return _handle_component_fixes(
                method,
                environ,
                suffix[: -len("/component-fixes")],
                start_response,
            )
        if separator and suffix.endswith("/notifications"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without recording any notification.
            return _handle_notifications(
                method,
                environ,
                suffix[: -len("/notifications")],
                start_response,
            )
        if separator and "/notifications/" in suffix:
            # Fallback for a separator inside the id segment of a
            # notification item path so the handler rejects it without
            # removing any record.
            malformed_id, _, raw_notification_id = suffix.rpartition(
                "/notifications/"
            )
            return _handle_notification_item(
                method,
                environ,
                malformed_id,
                raw_notification_id,
                start_response,
            )
        if separator and suffix.endswith(
            "/dependency-vulnerability-impact"
        ):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without computing any impact.
            return _handle_dependency_vulnerability_impact(
                method,
                environ,
                suffix[: -len("/dependency-vulnerability-impact")],
                start_response,
            )
        if separator and suffix.endswith("/cross-references"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without resolving anything.
            return _handle_cross_references(
                method,
                environ,
                suffix[: -len("/cross-references")],
                start_response,
            )
        if separator and "/cross-references/" in suffix:
            # Fallback for a separator inside the id segment on a single
            # reference item path so the handler rejects it without
            # removing any record.
            malformed_id, _, raw_item = suffix.rpartition(
                "/cross-references/"
            )
            return _handle_cross_reference_item(
                method,
                environ,
                malformed_id,
                raw_item,
                start_response,
            )
        if separator and suffix.endswith("/signatures/verify"):
            # Fallback for a separator inside the id segment so the
            # verify handler rejects it without checking any record.
            return _handle_signature_verify(
                method,
                environ,
                suffix[: -len("/signatures/verify")],
                start_response,
            )
        if separator and suffix.endswith("/signatures"):
            # Fallback for a separator inside the id segment so the
            # handler rejects it without recording any signature.
            return _handle_signatures(
                method,
                environ,
                suffix[: -len("/signatures")],
                start_response,
            )
        # Any other suffix keeps the baseline item semantics (embedded
        # separators are rejected by the item handler).
        return _handle_resource_item(
            method, environ, suffix, start_response
        )

    # Unknown paths and undeclared methods on /health stay as before.
    return _json_response(
        start_response,
        "404 Not Found",
        {"error": "not_found", "message": "The requested resource does not exist."},
    )
except Exception:  # pragma: no cover - defensive boundary
    # Clients must only ever see agreed statuses, never a stack trace.
    return _error(
        start_response,
        "500 Internal Server Error",
        "internal_error",
        "An unexpected error occurred.",
    )

def _handle_resources_get(
    environ: dict[str, Any], start_response: StartResponse
) -> Iterable[bytes]:
    try:
        query = parse_list_query(str(environ.get("QUERY_STRING", "")))
    except ListQueryError as exc:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            str(exc),
        )

    if not query.paged:
        # No filtering or pagination parameters: preserve the original shape.
        return _json_response(
            start_response,
            "200 OK",
            {"resources": [r.to_dict() for r in store.list_all()]},
            trailing_newline=True,
        )

    matched = store.query(
        category=query.category, name=query.name, digest=query.digest
    )
    page = matched[query.offset : query.offset + query.limit]
    next_offset = query.offset + len(page)
    next_cursor: str | None = None
    if next_offset < len(matched):
        next_cursor = _encode_cursor(
            query.category or "",
            query.name or "",
            query.digest or "",
            query.limit,
            next_offset,
        )

    return _json_response(
        start_response,
        "200 OK",
        {"resources": [r.to_dict() for r in page], "next_cursor": next_cursor},
        trailing_newline=True,
    )


def _json_response(
    start_response: StartResponse,
    status: str,
    payload: object,
    *,
    extra_headers: list[tuple[str, str]] | None = None,
    trailing_newline: bool = False,
) -> Iterable[bytes]:
    body = json.dumps(
        payload,
        ensure_ascii=False,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    if trailing_newline:
        body += b"\n"
    headers = [
        ("Content-Type", "application/json; charset=utf-8"),
        ("Content-Length", str(len(body))),
    ]
    if extra_headers:
        headers.extend(extra_headers)
    start_response(status, headers)
    return [body]


def _error(
    start_response: StartResponse,
    status: str,
    code: str,
    message: str,
    *,
    allowed: str | None = None,
    trailing_newline: bool = True,
    extra_headers: list[tuple[str, str]] | None = None,
) -> Iterable[bytes]:
    headers = list(extra_headers) if extra_headers else []
    if allowed is not None:
        headers.append(("Allow", allowed))
    return _json_response(
        start_response,
        status,
        {"error": code, "message": message},
        extra_headers=headers,
        trailing_newline=trailing_newline,
    )


def _resource_response(
    start_response: StartResponse, status: str, resource: Resource
) -> Iterable[bytes]:
    return _json_response(
        start_response,
        status,
        resource.to_dict(),
        trailing_newline=True,
    )


def _read_body(environ: dict[str, Any]) -> bytes:
    try:
        length = int(environ.get("CONTENT_LENGTH") or 0)
    except (TypeError, ValueError):
        length = 0
    if length <= 0:
        return b""
    return environ["wsgi.input"].read(length)


def _handle_resources_post(
    environ: dict[str, Any], start_response: StartResponse
) -> Iterable[bytes]:
    raw = _read_body(environ)
    if not raw:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body is empty.",
        )
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            "Request body must be valid UTF-8 JSON.",
        )

    try:
        created, existing = store.add(payload)
    except ResourceValidationError as exc:
        return _error(
            start_response,
            "400 Bad Request",
            "invalid_request",
            exc.message,
        )

    if existing is not None:
        # Never overwrite or merge with the original record.
        return _error(
            start_response,
            "409 Conflict",
            "duplicate_resource",
            "A resource with the same category, name and digest already exists.",
        )

    assert created is not None
    return _resource_response(start_response, "201 Created", created)


def _remove_resource_cascade(resource_id: str) -> None:
    """Remove every record keyed by ``resource_id`` across all stores.

    Alerts, exemptions, SBOM and license data, provenance, policies,
    signatures, notifications, lifecycle state, chunk sessions with their
    assembled bytes, cross-repository references and dependency edges all
    disappear with the resource; derived read-only views (advisory
    summaries, component views, admission previews, risk scores) are
    computed on the fly and therefore reflect the removal immediately.
    Mirror sources, cache entries and other resources are never touched.
    """

    vulnerability_store.remove_resource(resource_id)
    vulnerability_exception_store.remove_resource(resource_id)
    sbom_store.remove_resource(resource_id)
    provenance_store.remove_resource(resource_id)
    policy_store.remove_resource(resource_id)
    signature_store.remove_resource(resource_id)
    notification_store.remove_resource(resource_id)
    lifecycle_store.remove(resource_id)
    content_store.remove(resource_id)
    cross_reference_store.remove_resource(resource_id)
    store.remove(resource_id)


def _handle_resource_item(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method not in ("GET", "DELETE"):
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="DELETE, GET",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )

    if method == "GET":
        resource = store.get(raw_id)
        if resource is None:
            return _error(
                start_response,
                "404 Not Found",
                "resource_not_found",
                "No resource exists with the requested id.",
            )
        return _resource_response(start_response, "200 OK", resource)

    # DELETE: a bodyless, parameterless request that unregisters the
    # resource and cascades to every record stored under its id.
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    body_error = _bodyless_request_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    resource = store.get(raw_id)
    if resource is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    _remove_resource_cascade(raw_id)
    return _resource_response(start_response, "200 OK", resource)


def _validate_path_id(raw_id: str) -> str | None:
    """Return a stable error message for an invalid path id, else ``None``."""

    if not raw_id:
        return "Resource id must not be empty."
    if "/" in raw_id or "\\" in raw_id:
        return "Resource id must not contain path separators."
    return None


def _decode_reference_segment(raw_segment: str, label: str) -> tuple[str, str | None]:
    """Percent-decode one cross-reference item path segment.

    Returns ``(decoded, None)`` or ``(None, message)``. The segment is
    decoded as a path segment and then matched verbatim against the stored
    value; an empty segment or one that decodes to contain a path
    separator (``/`` or ``\\``, including ``%2F``/``%5C``) is rejected.
    """

    decoded = unquote(raw_segment)
    if not decoded:
        return None, f"{label} path segment must not be empty."
    if "/" in decoded or "\\" in decoded:
        return None, f"{label} path segment must not contain path separators."
    return decoded, None


def _query_parameter_error(environ: dict[str, Any]) -> str | None:
    """Reject any query parameter on endpoints that declare none."""

    query_string = str(environ.get("QUERY_STRING", ""))
    if parse_qsl(query_string, keep_blank_values=True):
        return "This endpoint does not accept query parameters."
    return None


def _handle_dependencies_post(
    environ: dict[str, Any], raw_id: str, start_response: StartResponse
) -> Iterable[bytes]:

def _admission_body_error(environ: dict[str, Any]) -> str | None:
    """Reject an admission request that declares or carries a body."""

    raw_length = environ.get("CONTENT_LENGTH")
    if raw_length is None:
        return None
    if (
        not isinstance(raw_length, str)
        or _NON_NEGATIVE_INT_PATTERN.fullmatch(raw_length) is None
        or int(raw_length) > 0
    ):
        return "This endpoint does not accept a request body."
    return None


def _bodyless_request_error(environ: dict[str, Any]) -> str | None:
    """Reject a bodyless endpoint (cache DELETE) that declares a body.

    Unlike admission, this also treats an empty-string ``Content-Length``
    as no body: a real WSGI server seeds ``CONTENT_LENGTH`` with ``''``
    for requests that omit the header entirely (e.g. curl's bodyless
    DELETE), so only a declared positive or malformed length is rejected.
    An explicit ``Content-Length: 0`` is an empty body and is accepted.
    """

    raw_length = environ.get("CONTENT_LENGTH")
    if raw_length is None or raw_length == "":
        return None
    if (
        not isinstance(raw_length, str)
        or _NON_NEGATIVE_INT_PATTERN.fullmatch(raw_length) is None
        or int(raw_length) > 0
    ):
        return "This endpoint does not accept a request body."
    return None


def _handle_admission(
    method: str,
    environ: dict[str, Any],
    raw_id: str,
    start_response: StartResponse,
) -> Iterable[bytes]:
    if method != "POST":
        return _error(
            start_response,
            "405 Method Not Allowed",
            "method_not_allowed",
            f"Method {method} is not allowed for this path.",
            allowed="POST",
        )

    id_error = _validate_path_id(raw_id)
    if id_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", id_error
        )
    query_error = _query_parameter_error(environ)
    if query_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", query_error
        )
    body_error = _admission_body_error(environ)
    if body_error is not None:
        return _error(
            start_response, "400 Bad Request", "invalid_request", body_error
        )

    if store.get(raw_id) is None:
        return _error(
            start_response,
            "404 Not Found",
            "resource_not_found",
            "No resource exists with the requested id.",
        )

    policy = policy_store.get(raw_id)
    if policy is None:
        # Resources without their own policy fall back to the single
        # global default policy; the evaluation itself is unchanged.
        policy = default_policy_store.get()
    if policy is None:
        return _error(
            start_response,
            "404 Not Found",
            "policy_not_found",
            "No policy is registered for this resource.",
        )

    license_record = sbom_store.get_license(raw_id)
    allowed, reasons = evaluate_policy(
        policy,
        lifecycle_state=lifecycle_store.get(raw_id).state,
        has_sbom=sbom_store.get_sbom(raw_id) is not None,
        has_license=license_record is not None,
        has_provenance=provenance_store.get(raw_id) is not None,
        has_signature=signature_store.get(raw_id) is not None,
        license_spdx_id=(
            license_record.spdx_id if license_record is not None else None
        ),

"""In-process SBOM documents and license declarations for resources.

Each resource keeps at most one SBOM document and at most one license
declaration. SBOM components are preserved in submission order together
with their name, version and lowercase 64-character hexadecimal digest.
Nothing here is persisted: stopping or restarting the service clears
every document and license, and no files are written.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

#: The two accepted SBOM document formats; input is case-sensitive.
FORMATS: tuple[str, ...] = ("spdx", "cyclonedx")
FORMAT_VALUES = frozenset(FORMATS)

#: A component digest is exactly 64 hexadecimal characters; mixed case is
#: accepted but the digest is always stored and rendered in lowercase.
_DIGEST_PATTERN = re.compile(r"[0-9a-fA-F]{64}")

#: Fields accepted by the SBOM registration request; anything else is
#: rejected. Both fields are required (``components`` may be an empty list).
_SBOM_ALLOWED_FIELDS = frozenset({"format", "components"})

#: Fields accepted by the license registration request; ``source`` is
#: optional and is rendered as ``null`` when omitted.
_LICENSE_ALLOWED_FIELDS = frozenset({"spdx_id", "source"})


class SbomValidationError(ValueError):
    """An SBOM or license payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class SbomError(ValueError):
    """An SBOM or license operation could not proceed.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class SbomComponent:
    """A single SBOM component identified by name, version and digest."""

    name: str
    version: str
    digest: str

    def to_dict(self) -> dict[str, object]:
        return {"name": self.name, "version": self.version, "digest": self.digest}


@dataclass(frozen=True, slots=True)
class SbomDocument:
    """The single SBOM document recorded against a resource."""

    format: str
    components: tuple[SbomComponent, ...]

    def to_dict(self, resource_id: str) -> dict[str, object]:
        return {
            "id": resource_id,
            "format": self.format,
            "components": [component.to_dict() for component in self.components],
        }


@dataclass(frozen=True, slots=True)
class LicenseRecord:
    """The single license declaration recorded against a resource."""

    spdx_id: str
    source: str | None

    def to_dict(self, resource_id: str) -> dict[str, object]:
        return {"id": resource_id, "spdx_id": self.spdx_id, "source": self.source}


def _require_non_empty_string(value: object, label: str) -> str:
    if not isinstance(value, str):
        raise SbomValidationError(f"{label} must be a string.")
    if not value:
        raise SbomValidationError(f"{label} must not be empty.")
    return value


def build_sbom_fields(payload: object) -> tuple[str, tuple[SbomComponent, ...]]:
    """Validate a decoded SBOM payload and return normalized values.

    Returns ``(format, components)``. ``format`` must be ``spdx`` or
    ``cyclonedx`` (case-sensitive); ``components`` must be a list (possibly
    empty) of objects whose ``name``, ``version`` and ``digest`` are
    non-empty strings, with ``digest`` normalized to lowercase. Components
    are returned in their submitted order.
    """

    if not isinstance(payload, dict):
        raise SbomValidationError("Request body must be a JSON object.")

    unknown_fields = set(payload) - _SBOM_ALLOWED_FIELDS
    if unknown_fields:
        raise SbomValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    if "format" not in payload:
        raise SbomValidationError("Missing required field: 'format'.")
    format_value = payload["format"]
    if not isinstance(format_value, str) or format_value not in FORMAT_VALUES:
        raise SbomValidationError(
            "Field 'format' must be one of: spdx, cyclonedx."
        )

    if "components" not in payload:
        raise SbomValidationError("Missing required field: 'components'.")
    raw_components = payload["components"]
    if not isinstance(raw_components, list):
        raise SbomValidationError("Field 'components' must be an array.")

    components: list[SbomComponent] = []
    for position, raw_component in enumerate(raw_components):
        if not isinstance(raw_component, dict):
            raise SbomValidationError(
                f"Component at index {position} must be a JSON object."
            )
        component_unknown = set(raw_component) - {"name", "version", "digest"}
        if component_unknown:
            raise SbomValidationError(
                f"Unknown field: {sorted(component_unknown)[0]!r}."
            )
        for field in ("name", "version", "digest"):
            if field not in raw_component:
                raise SbomValidationError(
                    f"Component at index {position} is missing required "
                    f"field: {field!r}."
                )
        name = _require_non_empty_string(
            raw_component["name"], "Component field 'name'"
        )
        version = _require_non_empty_string(
            raw_component["version"], "Component field 'version'"
        )
        raw_digest = raw_component["digest"]
        if (
            not isinstance(raw_digest, str)
            or _DIGEST_PATTERN.fullmatch(raw_digest) is None
        ):
            raise SbomValidationError(
                "Component field 'digest' must be a 64-character "
                "hexadecimal string."
            )
        components.append(
            SbomComponent(name=name, version=version, digest=raw_digest.lower())
        )

    return format_value, tuple(components)


def build_license_fields(payload: object) -> tuple[str, str | None]:
    """Validate a decoded license payload and return ``(spdx_id, source)``."""

    if not isinstance(payload, dict):
        raise SbomValidationError("Request body must be a JSON object.")

    unknown_fields = set(payload) - _LICENSE_ALLOWED_FIELDS
    if unknown_fields:
        raise SbomValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    if "spdx_id" not in payload:
        raise SbomValidationError("Missing required field: 'spdx_id'.")
    spdx_id = _require_non_empty_string(payload["spdx_id"], "Field 'spdx_id'")

    source: str | None = None
    if "source" in payload:
        source = _require_non_empty_string(payload["source"], "Field 'source'")

    return spdx_id, source


class SbomStore:
    """Process-local storage of at most one SBOM and license per resource."""

    def __init__(self) -> None:
        self._sboms: dict[str, SbomDocument] = {}
        self._licenses: dict[str, LicenseRecord] = {}

    def reset(self) -> None:
        self._sboms = {}
        self._licenses = {}

    def remove_resource(self, resource_id: str) -> None:
        """Remove any SBOM document and license declaration for a resource.

        An unknown id is a no-op.
        """

        self._sboms.pop(resource_id, None)
        self._licenses.pop(resource_id, None)

    # --- SBOM --------------------------------------------------------------

    def add_sbom(
        self, resource_id: str, payload: object
    ) -> tuple[SbomDocument, bool]:
        """Validate and record the SBOM document for ``resource_id``.

        Returns ``(document, created)`` where ``created`` is ``True`` for a
        first registration (HTTP 201) and ``False`` for an idempotent repeat
        of the exact same document (HTTP 200).

        Raises :class:`SbomValidationError` for an invalid payload,
        :class:`SbomError` with code ``duplicate_component`` when the
        submitted components repeat a name/version/digest triple, or
        ``sbom_conflict`` when a different document is already recorded;
        the stored document is never modified.
        """

        format_value, components = build_sbom_fields(payload)

        seen: set[tuple[str, str, str]] = set()
        for component in components:
            triple = (component.name, component.version, component.digest)
            if triple in seen:
                raise SbomError(
                    "duplicate_component",
                    "An identical component (same name, version and "
                    "digest) is listed more than once.",
                )
            seen.add(triple)

        document = SbomDocument(format=format_value, components=components)

        existing = self._sboms.get(resource_id)
        if existing is not None:
            if existing == document:
                return existing, False
            raise SbomError(
                "sbom_conflict",
                "A different SBOM document is already recorded for this "
                "resource.",
            )

        self._sboms[resource_id] = document
        return document, True

    def get_sbom(self, resource_id: str) -> SbomDocument | None:
        return self._sboms.get(resource_id)

    # --- License -----------------------------------------------------------

    def add_license(
        self, resource_id: str, payload: object
    ) -> tuple[LicenseRecord, bool]:
        """Validate and record the license declaration for ``resource_id``.

        Returns ``(record, created)`` with ``created`` ``False`` for an
        idempotent repeat of the same declaration (HTTP 200). A different
        declaration raises :class:`SbomError` with code
        ``license_conflict``; the stored declaration is left untouched.
        """

        spdx_id, source = build_license_fields(payload)
        record = LicenseRecord(spdx_id=spdx_id, source=source)

        existing = self._licenses.get(resource_id)
        if existing is not None:
            if existing == record:
                return existing, False
            raise SbomError(
                "license_conflict",
                "A different license is already declared for this resource.",
            )

        self._licenses[resource_id] = record
        return record, True

    def get_license(self, resource_id: str) -> LicenseRecord | None:
        return self._licenses.get(resource_id)

"""In-process build provenance records for registered resources.

Each resource keeps at most one provenance record describing a single
build: the builder, a build number, a source summary digest and a list of
materials. Digests are normalized to lowercase and materials keep their
submission order. Nothing here is persisted: stopping or restarting the
service clears every record, no signatures are verified, and promotion
rules are unaffected.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

#: A digest is exactly 64 hexadecimal characters; mixed case is accepted
#: but the digest is always stored and rendered in lowercase.
_DIGEST_PATTERN = re.compile(r"[0-9a-fA-F]{64}")

#: Text fields are non-empty and bounded by 256 Unicode code points.
MAX_TEXT_LENGTH = 256

#: Fields accepted by the registration request; anything else is rejected.
_ALLOWED_FIELDS = frozenset(
    {"builder", "build_number", "source_digest", "materials"}
)
_REQUIRED_FIELDS = ("builder", "build_number", "source_digest", "materials")
_MATERIAL_FIELDS = frozenset({"name", "digest"})


class ProvenanceValidationError(ValueError):
    """A provenance payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class ProvenanceError(ValueError):
    """A provenance operation could not proceed.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class Material:
    """A single build material identified by name and digest."""

    name: str
    digest: str

    def to_dict(self) -> dict[str, object]:
        return {"name": self.name, "digest": self.digest}


@dataclass(frozen=True, slots=True)
class ProvenanceRecord:
    """The single build provenance record stored for a resource."""

    builder: str
    build_number: str
    source_digest: str
    materials: tuple[Material, ...]

    def to_dict(self, resource_id: str) -> dict[str, object]:
        return {
            "id": resource_id,
            "builder": self.builder,
            "build_number": self.build_number,
            "source_digest": self.source_digest,
            "materials": [material.to_dict() for material in self.materials],
        }


def _required_text(value: object, label: str) -> str:
    """Validate a required non-empty string of at most 256 code points."""

    if not isinstance(value, str):
        raise ProvenanceValidationError(f"{label} must be a string.")
    if not value:
        raise ProvenanceValidationError(f"{label} must not be empty.")
    if len(value) > MAX_TEXT_LENGTH:
        raise ProvenanceValidationError(
            f"{label} must not exceed {MAX_TEXT_LENGTH} Unicode code points."
        )
    return value


def _require_digest(value: object, label: str) -> str:
    if not isinstance(value, str) or _DIGEST_PATTERN.fullmatch(value) is None:
        raise ProvenanceValidationError(
            f"{label} must be a 64-character hexadecimal string."
        )
    return value.lower()


def build_provenance_fields(
    payload: object,
) -> tuple[str, str, str, tuple[Material, ...]]:
    """Validate a decoded provenance payload and return normalized values.

    Returns ``(builder, build_number, source_digest, materials)``. The
    source and material digests are normalized to lowercase and materials
    are returned in their submitted order (an empty material list is
    allowed). Repeated materials (same name and normalized digest) are a
    validation error.
    """

    if not isinstance(payload, dict):
        raise ProvenanceValidationError("Request body must be a JSON object.")

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise ProvenanceValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise ProvenanceValidationError(
                f"Missing required field: {field!r}."
            )

    builder = _required_text(payload["builder"], "Field 'builder'")
    build_number = _required_text(
        payload["build_number"], "Field 'build_number'"
    )
    source_digest = _require_digest(
        payload["source_digest"], "Field 'source_digest'"
    )

    raw_materials = payload["materials"]
    if not isinstance(raw_materials, list):
        raise ProvenanceValidationError("Field 'materials' must be an array.")

    materials: list[Material] = []
    seen: set[tuple[str, str]] = set()
    for position, raw_material in enumerate(raw_materials):
        if not isinstance(raw_material, dict):
            raise ProvenanceValidationError(
                f"Material at index {position} must be a JSON object."
            )
        material_unknown = set(raw_material) - _MATERIAL_FIELDS
        if material_unknown:
            raise ProvenanceValidationError(
                f"Unknown field: {sorted(material_unknown)[0]!r}."
            )
        for field in ("name", "digest"):
            if field not in raw_material:
                raise ProvenanceValidationError(
                    f"Material at index {position} is missing required "
                    f"field: {field!r}."
                )
        name = _required_text(
            raw_material["name"], "Material field 'name'"
        )
        digest = _require_digest(
            raw_material["digest"], "Material field 'digest'"
        )
        key = (name, digest)
        if key in seen:
            raise ProvenanceValidationError(
                "A material with the same name and digest is listed more "
                "than once."
            )
        seen.add(key)
        materials.append(Material(name=name, digest=digest))

    return builder, build_number, source_digest, tuple(materials)


class ProvenanceStore:
    """Process-local storage of at most one provenance record per resource."""

    def __init__(self) -> None:
        self._records: dict[str, ProvenanceRecord] = {}

    def reset(self) -> None:
        self._records = {}

    def remove_resource(self, resource_id: str) -> None:
        """Remove any provenance record for a resource.

        An unknown id is a no-op.
        """

        self._records.pop(resource_id, None)

    def add(
        self, resource_id: str, payload: object
    ) -> tuple[ProvenanceRecord, bool]:
        """Validate and record the provenance for ``resource_id``.

        Returns ``(record, created)`` where ``created`` is ``True`` for a
        first registration (HTTP 201) and ``False`` for an idempotent repeat
        of the exact same normalized content (HTTP 200).

        Raises :class:`ProvenanceValidationError` for an invalid payload or
        :class:`ProvenanceError` with code ``provenance_conflict`` when a
        different record is already stored; the stored record is never
        overwritten.
        """

        builder, build_number, source_digest, materials = (
            build_provenance_fields(payload)
        )
        record = ProvenanceRecord(
            builder=builder,
            build_number=build_number,
            source_digest=source_digest,
            materials=materials,
        )

        existing = self._records.get(resource_id)
        if existing is not None:
            if existing == record:
                return existing, False
            raise ProvenanceError(
                "provenance_conflict",
                "A different provenance record is already registered for "
                "this resource.",
            )

        self._records[resource_id] = record
        return record, True

    def get(self, resource_id: str) -> ProvenanceRecord | None:
        return self._records.get(resource_id)

"""In-process content signatures for registered resources.

Each resource keeps at most one signature record naming the signer, the
HMAC algorithm, the key id, the hexadecimal signature value and the
signed digest. Text is kept verbatim while hexadecimal values are
normalized to lowercase. Nothing here is persisted: stopping or
restarting the service clears every record.
"""

from __future__ import annotations

import hashlib
import hmac
import re
from dataclasses import dataclass

#: A digest is exactly 64 hexadecimal characters; mixed case is accepted
#: but the digest is always stored in lowercase.
_DIGEST_PATTERN = re.compile(r"[0-9a-fA-F]{64}")

#: Text fields are non-empty and bounded by 256 Unicode code points.
MAX_TEXT_LENGTH = 256

#: The two supported HMAC algorithms and their hexadecimal output lengths.
ALGORITHMS: tuple[str, ...] = ("hmac-sha256", "hmac-sha512")
_ALGORITHM_HASHES = {
    "hmac-sha256": hashlib.sha256,
    "hmac-sha512": hashlib.sha512,
}
_HEX_LENGTHS = {"hmac-sha256": 64, "hmac-sha512": 128}
_HEX_PATTERNS = {
    algorithm: re.compile(r"[0-9a-fA-F]{%d}" % length)
    for algorithm, length in _HEX_LENGTHS.items()
}

#: Fields accepted by the registration request; anything else is rejected.
_ALLOWED_FIELDS = frozenset(
    {"signer", "algorithm", "key_id", "signature", "digest"}
)
_REQUIRED_FIELDS = ("signer", "algorithm", "key_id", "signature", "digest")


class SignatureValidationError(ValueError):
    """A signature payload failed field-level validation."""

    def __init__(self, message: str) -> None:
        super().__init__(message)
        self.message = message


class SignatureError(ValueError):
    """A signature operation could not proceed.

    ``code`` is the stable, client-facing error code.
    """

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


@dataclass(frozen=True, slots=True)
class SignatureRecord:
    """The single content signature record stored for a resource."""

    signer: str
    algorithm: str
    key_id: str
    signature: str
    digest: str

    def to_dict(self, resource_id: str) -> dict[str, object]:
        return {
            "id": resource_id,
            "signer": self.signer,
            "algorithm": self.algorithm,
            "key_id": self.key_id,
            "signature": self.signature,
            "digest": self.digest,
        }


def _required_text(value: object, label: str) -> str:
    """Validate a required non-empty string of at most 256 code points."""

    if not isinstance(value, str):
        raise SignatureValidationError(f"{label} must be a string.")
    if not value:
        raise SignatureValidationError(f"{label} must not be empty.")
    if len(value) > MAX_TEXT_LENGTH:
        raise SignatureValidationError(
            f"{label} must not exceed {MAX_TEXT_LENGTH} Unicode code points."
        )
    return value


def _require_digest(value: object) -> str:
    if not isinstance(value, str) or _DIGEST_PATTERN.fullmatch(value) is None:
        raise SignatureValidationError(
            "Field 'digest' must be a 64-character hexadecimal string."
        )
    return value.lower()


def build_signature_fields(
    payload: object,
) -> tuple[str, str, str, str, str]:
    """Validate a decoded signature payload and return normalized values.

    Returns ``(signer, algorithm, key_id, signature, digest)``. The digest
    and signature hexadecimal values are normalized to lowercase; the
    signature length must match its algorithm (64 characters for
    HMAC-SHA256 and 128 for HMAC-SHA512).
    """

    if not isinstance(payload, dict):
        raise SignatureValidationError("Request body must be a JSON object.")

    unknown_fields = set(payload) - _ALLOWED_FIELDS
    if unknown_fields:
        raise SignatureValidationError(
            f"Unknown field: {sorted(unknown_fields)[0]!r}."
        )

    for field in _REQUIRED_FIELDS:
        if field not in payload:
            raise SignatureValidationError(
                f"Missing required field: {field!r}."
            )

    signer = _required_text(payload["signer"], "Field 'signer'")

    algorithm = payload["algorithm"]
    if not isinstance(algorithm, str) or algorithm not in _ALGORITHM_HASHES:
        allowed = ", ".join(ALGORITHMS)
        raise SignatureValidationError(
            f"Field 'algorithm' must be one of: {allowed} (case-sensitive)."
        )

    key_id = _required_text(payload["key_id"], "Field 'key_id'")

    raw_signature = payload["signature"]
    if (
        not isinstance(raw_signature, str)
        or _HEX_PATTERNS[algorithm].fullmatch(raw_signature) is None
    ):
        expected_length = _HEX_LENGTHS[algorithm]
        raise SignatureValidationError(
            f"Field 'signature' must be a {expected_length}-character "
            "hexadecimal string matching its algorithm."
        )
    signature = raw_signature.lower()

    digest = _require_digest(payload["digest"])

    return signer, algorithm, key_id, signature, digest


def compute_signature(algorithm: str, key_id: str, digest: str) -> str:
    """Recompute the lowercase hexadecimal HMAC for a stored record.

    The key is the UTF-8 byte sequence of ``key_id`` and the signed message
    is the lowercase hexadecimal digest text.
    """

    return hmac.new(
        key_id.encode("utf-8"),
        digest.encode("ascii"),
        _ALGORITHM_HASHES[algorithm],
    ).hexdigest()


class SignatureStore:
    """Process-local storage of at most one signature record per resource."""

    def __init__(self) -> None:
        self._records: dict[str, SignatureRecord] = {}

    def reset(self) -> None:
        self._records = {}

    def remove_resource(self, resource_id: str) -> None:
        """Remove any signature record for a resource.

        An unknown id is a no-op.
        """

        self._records.pop(resource_id, None)

    def add(
        self, resource_id: str, payload: object
    ) -> tuple[SignatureRecord, bool]:
        """Validate and record the signature for ``resource_id``.

        Returns ``(record, created)`` where ``created`` is ``True`` for a
        first registration (HTTP 201) and ``False`` for an idempotent repeat
        of the exact same normalized content (HTTP 200).

        Raises :class:`SignatureValidationError` for an invalid payload or
        :class:`SignatureError` with code ``signature_conflict`` when a
        different record is already stored; the stored record is never
        overwritten.
        """

        signer, algorithm, key_id, signature, digest = (
            build_signature_fields(payload)
        )
        record = SignatureRecord(
            signer=signer,
            algorithm=algorithm,
            key_id=key_id,
            signature=signature,
            digest=digest,
        )

        existing = self._records.get(resource_id)
        if existing is not None:
            if existing == record:
                return existing, False
            raise SignatureError(
                "signature_conflict",
                "A different signature record is already registered for "
                "this resource.",
            )

        self._records[resource_id] = record
        return record, True

    def get(self, resource_id: str) -> SignatureRecord | None:
        return self._records.get(resource_id)

